package app.repositories;

import app.common.Page;
import app.entities.Customer;
import java.util.List;
import java.util.Optional;

/** Where customers rows are kept. Services depend only on this interface. */
public interface CustomerRepository {
    /** The row with this primary key, if there is one. */
    Optional<Customer> findById(String id);

    /** At most limit rows from offset, by primary key, and how many there are. */
    Page<Customer> list(int offset, int limit);

    /** The row with this email, if there is one. */
    Optional<Customer> findByEmail(String email);

    /** Stores a new row; the values the database fills are read back. */
    Customer insert(Customer entity);

    /** Stores the changes made to a row read from this repository. */
    Customer update(Customer entity);

    /** Removes a row read from this repository. */
    void delete(Customer entity);

    /** Adds an item to tags, and gives the row as it is then, if there is one. */
    Optional<Customer> addTag(String id, String tag);

    /** Removes an item from tags, and gives the row as it is then, if there is one. */
    Optional<Customer> removeTag(String id, String tag);
}

