    }

    /** The Order as services return it. */
    private static OrderRead read(Order entity) {
        return new OrderRead(entity.getId(), entity.getCode(), entity.getLines(), entity.getShipping());
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(OrderUpdate changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.code() != null && changes.code().isPresent()) values.put("code", changes.code().value());
        if (changes.lines() != null && changes.lines().isPresent()) values.put("lines", changes.lines().value());
        if (changes.shipping() != null && changes.shipping().isPresent()) values.put("shipping", changes.shipping().value());
        return values;
    }

    /** What a Line does not follow of its rules, each with the path of its field. */
    private static void checkLine(Order.Line value, String path, List<FieldError> errors) {
        if (value.getSku() == null) errors.add(new FieldError(path + ".sku", "is required"));
        if (value.getQuantity() == null) errors.add(new FieldError(path + ".quantity", "is required"));
        if (value.getPrice() == null) errors.add(new FieldError(path + ".price", "is required"));
        if (value.getStatus() != null && !List.of("pending", "sent").contains(value.getStatus())) errors.add(new FieldError(path + ".status", "must be one of: pending, sent"));
        if (value.getDiscounts() != null) {
            for (int i0 = 0; i0 < value.getDiscounts().size(); i0++) {
                if (value.getDiscounts().get(i0) == null) errors.add(new FieldError(path + ".discounts" + "." + i0, "is required"));
                else checkLineDiscount(value.getDiscounts().get(i0), path + ".discounts" + "." + i0, errors);
            }
        }
    }

    /** What a Discount does not follow of its rules, each with the path of its field. */
    private static void checkLineDiscount(Order.Line.Discount value, String path, List<FieldError> errors) {
        if (value.getReason() == null) errors.add(new FieldError(path + ".reason", "is required"));
        if (value.getPercent() == null) errors.add(new FieldError(path + ".percent", "is required"));
    }

    /** What a Shipping does not follow of its rules, each with the path of its field. */
    private static void checkShipping(Order.Shipping value, String path, List<FieldError> errors) {
        if (value.getCarrier() == null) errors.add(new FieldError(path + ".carrier", "is required"));
        if (value.getSentOn() == null) errors.add(new FieldError(path + ".sentOn", "is required"));
    }

    /** Stores a new Order after checking it. */
    public OrderRead createOrder(OrderCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.code() != null) values.put("code", data.code());
        if (data.lines() != null) values.put("lines", data.lines());
        if (data.shipping() != null) values.put("shipping", data.shipping());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Order entity = new Order();
            apply(entity, values);
            return read(uow.orders().insert(entity));
        });
    }

    /** The Order with this key; NotFoundException when there is none. */
    public OrderRead getOrder(String id) {
        return read(find(uow, id));
    }

    /** A page of orders, by primary key. */
    public Page<OrderRead> listOrders(int offset, int limit) {
        return uow.orders().list(offset, limit).map(OrderService::read);
    }

    /** Changes the given values of a Order. */
    public OrderRead updateOrder(String id, OrderUpdate changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Order current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return read(uow.orders().update(current));
        });
    }

    /** Deletes a Order. */
    public void deleteOrder(String id) {
        uow.transaction((uow) -> {
            Order current = find(uow, id);
            uow.orders().delete(current);
            return null;
        });
    }

    /** The Order with this code, if there is one. */
    public Optional<OrderRead> findOrderByCode(String code) {
        return uow.orders().findByCode(code).map(OrderService::read);
    }

    /** Adds an item to lines. */
    public OrderRead addLine(String id, Order.Line line) {
        List<FieldError> errors = new ArrayList<>();
        checkLine(line, "lines", errors);
        if (!errors.isEmpty()) throw new ValidationFailedException("Order", errors);
        return uow.transaction((uow) -> {
            find(uow, id);
            return read(uow.orders().addLine(id, line).orElseThrow(() -> new NotFoundException("Order", id)));
        });
    }

    /** Removes an item from lines, by its identifier. */
    public OrderRead removeLine(String id, String lineId) {
        return uow.transaction((uow) -> {
            Order current = find(uow, id);
            if (current.getLines() == null || current.getLines().stream().noneMatch((item) -> lineId.equals(item.getId()))) throw new NotFoundException("Line", lineId);
            return read(uow.orders().removeLine(id, lineId).orElseThrow(() -> new NotFoundException("Order", id)));
        });
    }
}

