package app.services;

import app.UnitOfWork;
import app.common.Page;
import app.dtos.ShipmentCreate;
import app.dtos.ShipmentRead;
import app.dtos.ShipmentUpdate;
import app.entities.Shipment;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Operations on shipments. Repositories commit every write. */
public class ShipmentService {
    private final UnitOfWork uow;

    public ShipmentService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "shipments" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Shipment current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("parcel");
            if (value == null) {
                if (creating || values.containsKey("parcel")) errors.add(new FieldError("parcel", "is required"));
            } else {
                Shipment.Parcel document = (Shipment.Parcel) value;
                if (document != null) checkParcel(document, "parcel", errors);
            }
        }
        {
            Object value = values.get("stops");
            if (value != null) {
                @SuppressWarnings("unchecked")
                List<Shipment.Stop> document = (List<Shipment.Stop>) value;
                if (document != null) {
                    for (int i0 = 0; i0 < document.size(); i0++) {
                        if (document.get(i0) == null) errors.add(new FieldError("stops" + "." + i0, "is required"));
                        else checkStop(document.get(i0), "stops" + "." + i0, errors);
                    }
                }
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Shipment", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Shipment current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    @SuppressWarnings("unchecked")
    private static void apply(Shipment entity, Map<String, Object> values) {
        if (values.containsKey("parcel")) entity.setParcel((Shipment.Parcel) values.get("parcel"));
        if (values.containsKey("stops")) entity.setStops((List<Shipment.Stop>) values.get("stops"));
    }

    /** The Shipment with this key; NotFoundException when there is none. */
    private Shipment find(UnitOfWork uow, String id) {
        return uow.shipments().findById(id).orElseThrow(() -> new NotFoundException("Shipment", id));
    }

    /** The Shipment as services return it. */
    private static ShipmentRead read(Shipment entity) {
        return new ShipmentRead(entity.getId(), entity.getParcel(), entity.getStops());
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(ShipmentUpdate changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.parcel() != null && changes.parcel().isPresent()) values.put("parcel", changes.parcel().value());
        if (changes.stops() != null && changes.stops().isPresent()) values.put("stops", changes.stops().value());
        return values;
    }

    /** What a Parcel does not follow of its rules, each with the path of its field. */
    private static void checkParcel(Shipment.Parcel value, String path, List<FieldError> errors) {
        if (value.getWeight() == null) errors.add(new FieldError(path + ".weight", "is required"));
        if (value.getContents() == null) errors.add(new FieldError(path + ".contents", "is required"));
        if (value.getSize() != null) checkParcelSize(value.getSize(), path + ".size", errors);
    }

    /** What a Size does not follow of its rules, each with the path of its field. */
    private static void checkParcelSize(Shipment.Parcel.Size value, String path, List<FieldError> errors) {
        if (value.getHeight() == null) errors.add(new FieldError(path + ".height", "is required"));
    }

    /** What a Stop does not follow of its rules, each with the path of its field. */
    private static void checkStop(Shipment.Stop value, String path, List<FieldError> errors) {
    }

    /** Stores a new Shipment after checking it. */
    public ShipmentRead createShipment(ShipmentCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.parcel() != null) values.put("parcel", data.parcel());
        if (data.stops() != null) values.put("stops", data.stops());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Shipment entity = new Shipment();
            apply(entity, values);
            return read(uow.shipments().insert(entity));
        });
    }

    /** The Shipment with this key; NotFoundException when there is none. */
    public ShipmentRead getShipment(String id) {
        return read(find(uow, id));
    }

    /** A page of shipments, by primary key. */
    public Page<ShipmentRead> listShipments(int offset, int limit) {
        return uow.shipments().list(offset, limit).map(ShipmentService::read);
    }

    /** Changes the given values of a Shipment. */
    public ShipmentRead updateShipment(String id, ShipmentUpdate changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Shipment current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return read(uow.shipments().update(current));
        });
    }

    /** Deletes a Shipment. */
    public void deleteShipment(String id) {
        uow.transaction((uow) -> {
            Shipment current = find(uow, id);
            uow.shipments().delete(current);
            return null;
        });
    }

    /** Adds an item to stops. */
    public ShipmentRead addStop(String id, Shipment.Stop stop) {
        List<FieldError> errors = new ArrayList<>();
        checkStop(stop, "stops", errors);
        if (!errors.isEmpty()) throw new ValidationFailedException("Shipment", errors);
        return uow.transaction((uow) -> {
            find(uow, id);
            return read(uow.shipments().addStop(id, stop).orElseThrow(() -> new NotFoundException("Shipment", id)));
        });
    }

    /** Removes an item from stops, by its position. */
    public ShipmentRead removeStop(String id, int position) {
        return uow.transaction((uow) -> {
            Shipment current = find(uow, id);
            if (current.getStops() == null || position < 0 || position >= current.getStops().size()) throw new NotFoundException("Stop", position);
            return read(uow.shipments().removeStop(id, position, current.getStops().size()).orElseThrow(() -> new ConflictException("Shipment", "was changed by someone else since it was read", List.of("stops"))));
        });
    }
}

