package app;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import app.conversions.CustomerConversions;
import app.conversions.OrderConversions;
import app.dtos.CustomerRead;
import app.dtos.OrderRead;
import app.entities.Customer;
import app.entities.Order;
import org.junit.jupiter.api.Test;

/** Tests of the conversions between the application models and the tables. */
class ConversionsTest {
    private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

    @Test
    void readsCustomerAndWritesItBack() {
        Customer row = Factories.addCustomer(uow, 1);
        var model = CustomerConversions.customerReadToCustomerModel(customerReadOf(row));
        var values = CustomerConversions.customerModelToCustomerCreate(model);
        assertEquals(row.getEmail(), values.email());
        assertEquals(row.getLevel(), values.level());
        assertEquals(row.getSince(), values.since());
        if (row.getAddress() != null) {
            assertEquals(row.getAddress().getStreet(), values.address().getStreet());
            assertEquals(row.getAddress().getZipCode(), values.address().getZipCode());
            if (row.getAddress().getLocation() != null) {
                assertEquals(row.getAddress().getLocation().getLatitude(), values.address().getLocation().getLatitude());
                assertEquals(row.getAddress().getLocation().getLongitude(), values.address().getLocation().getLongitude());
            } else assertEquals(row.getAddress().getLocation(), values.address().getLocation());
        } else assertEquals(row.getAddress(), values.address());
        assertEquals(row.getTags(), values.tags());
    }

    @Test
    void readsOrderAndWritesItBack() {
        Order row = Factories.addOrder(uow, 1);
        var model = OrderConversions.orderReadToOrderModel(orderReadOf(row));
        var values = OrderConversions.orderModelToOrderCreate(model);
        assertEquals(row.getCode(), values.code());
        if (row.getLines() != null && !row.getLines().isEmpty()) {
            assertEquals(row.getLines().get(0).getId(), values.lines().get(0).getId());
            assertEquals(row.getLines().get(0).getSku(), values.lines().get(0).getSku());
            assertEquals(row.getLines().get(0).getQuantity(), values.lines().get(0).getQuantity());
            assertEquals(row.getLines().get(0).getPrice(), values.lines().get(0).getPrice());
            assertEquals(row.getLines().get(0).getStatus(), values.lines().get(0).getStatus());
            if (row.getLines().get(0).getDiscounts() != null && !row.getLines().get(0).getDiscounts().isEmpty()) {
                assertEquals(row.getLines().get(0).getDiscounts().get(0).getReason(), values.lines().get(0).getDiscounts().get(0).getReason());
                assertEquals(row.getLines().get(0).getDiscounts().get(0).getPercent(), values.lines().get(0).getDiscounts().get(0).getPercent());
            } else assertEquals(row.getLines().get(0).getDiscounts(), values.lines().get(0).getDiscounts());
        } else assertEquals(row.getLines(), values.lines());
    }

    /** The row as the service returns it. */
    private static CustomerRead customerReadOf(Customer entity) {
        return new CustomerRead(entity.getId(), entity.getEmail(), entity.getLevel(), entity.getSince(), entity.getAddress(), entity.getTags());
    }

    /** The row as the service returns it. */
    private static OrderRead orderReadOf(Order entity) {
        return new OrderRead(entity.getId(), entity.getCode(), entity.getLines(), entity.getShipping());
    }
}

