package app;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import app.common.Patch;
import app.dtos.CustomerCreate;
import app.dtos.CustomerUpdate;
import app.entities.Customer;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import app.services.CustomerService;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "customers" table. */
class CustomerTest {
    /** The repositories over the test database, opened empty for every test */
    private MongoUnitOfWork uow;

    @BeforeEach
    void open() {
        uow = new MongoUnitOfWork(TestDatabase.open());
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Customer stored = Factories.addCustomer(uow, 1);
            Customer found = uow.customers().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
            assertTrue(uow.customers().findByEmail(stored.getEmail()).isPresent());
        }

        @Test
        void listsRowsByKey() {
            Factories.addCustomer(uow, 1);
            Factories.addCustomer(uow, 2);
            var page = uow.customers().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void addsAndRemovesOneItemOfTags() {
            Customer stored = Factories.addCustomer(uow, 1);
            int before = stored.getTags() == null ? 0 : stored.getTags().size();
            String item = "tags-" + 7;
            Customer added = uow.customers().addTag(stored.getId(), item).orElseThrow();
            assertEquals(before + 1, added.getTags().size());
            Customer removed = uow.customers().removeTag(stored.getId(), item).orElseThrow();
            assertEquals(before, removed.getTags().size());
        }

        @Test
        void isDeleted() {
            Customer stored = Factories.addCustomer(uow, 1);
            uow.customers().delete(stored);
            assertTrue(uow.customers().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class CustomerServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            CustomerService service = new CustomerService(uow);
            int n = 100;
            Customer row = Factories.newCustomer(1);
            var created = service.createCustomer(createOf(row));
            var found = service.getCustomer(created.id());
            assertEquals(created.id(), found.id());
        }

        @Test
        void refusesAMissingValue() {
            CustomerService service = new CustomerService(uow);
            int n = 100;
            Customer row = Factories.newCustomer(1);
            row.setEmail(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createCustomer(createOf(row)));
            assertEquals(List.of("email"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void refusesARepeatedUniqueValue() {
            CustomerService service = new CustomerService(uow);
            int n = 100;
            Customer row = Factories.newCustomer(1);
            var first = service.createCustomer(createOf(row));
            Customer again = Factories.newCustomer(2);
            again.setEmail(first.email());
            assertThrows(ConflictException.class, () -> service.createCustomer(createOf(again)));
        }

        @Test
        void keepsItsOwnUniqueValue() {
            CustomerService service = new CustomerService(uow);
            int n = 100;
            Customer row = Factories.newCustomer(1);
            var created = service.createCustomer(createOf(row));
            service.updateCustomer(created.id(), new CustomerUpdate(Patch.of(created.email()), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent()));
        }

        @Test
        void saysWhenARowIsMissing() {
            CustomerService service = new CustomerService(uow);
            assertThrows(NotFoundException.class, () -> service.getCustomer("ffffffffffffffffffffffff"));
        }

        @Test
        void addsAndRemovesOneItemOfTags() {
            CustomerService service = new CustomerService(uow);
            int n = 100;
            Customer row = Factories.newCustomer(1);
            var created = service.createCustomer(createOf(row));
            int before = created.tags() == null ? 0 : created.tags().size();
            String item = "tags-" + 7;
            var added = service.addTag(created.id(), item);
            assertEquals(before + 1, added.tags().size());
            var removed = service.removeTag(created.id(), item);
            assertEquals(before, removed.tags().size());
        }

        @Test
        void deletesARow() {
            CustomerService service = new CustomerService(uow);
            int n = 100;
            Customer row = Factories.newCustomer(1);
            var created = service.createCustomer(createOf(row));
            service.deleteCustomer(created.id());
            assertThrows(NotFoundException.class, () -> service.getCustomer(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static CustomerCreate createOf(Customer row) {
        return new CustomerCreate(row.getEmail(), row.getLevel(), row.getSince(), row.getAddress(), row.getTags());
    }
}

