import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import app.common.Patch;
import app.dtos.OrderCreate;
import app.dtos.OrderUpdate;
import app.entities.Order;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import app.services.OrderService;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "orders" table. */
class OrderTest {
    /** The repositories over the test database, opened empty for every test */
    private MongoUnitOfWork uow;

    @BeforeEach
    void open() {
        uow = new MongoUnitOfWork(TestDatabase.open());
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Order stored = Factories.addOrder(uow, 1);
            Order found = uow.orders().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
            assertTrue(uow.orders().findByCode(stored.getCode()).isPresent());
        }

        @Test
        void listsRowsByKey() {
            Factories.addOrder(uow, 1);
            Factories.addOrder(uow, 2);
            var page = uow.orders().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void addsAndRemovesOneItemOfLines() {
            Order stored = Factories.addOrder(uow, 1);
            int before = stored.getLines() == null ? 0 : stored.getLines().size();
            Order.Line item = Factories.newOrderLine(7);
            Order added = uow.orders().addLine(stored.getId(), item).orElseThrow();
            assertEquals(before + 1, added.getLines().size());
            Order removed = uow.orders().removeLine(stored.getId(), added.getLines().get(before).getId()).orElseThrow();
            assertEquals(before, removed.getLines().size());
        }

        @Test
        void isDeleted() {
            Order stored = Factories.addOrder(uow, 1);
            uow.orders().delete(stored);
            assertTrue(uow.orders().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class OrderServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            OrderService service = new OrderService(uow);
            int n = 100;
            Order row = Factories.newOrder(1);
            var created = service.createOrder(createOf(row));
            var found = service.getOrder(created.id());
            assertEquals(created.id(), found.id());
        }

        @Test
        void refusesAMissingValue() {
            OrderService service = new OrderService(uow);
            int n = 100;
            Order row = Factories.newOrder(1);
            row.setCode(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createOrder(createOf(row)));
            assertEquals(List.of("code"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void refusesARepeatedUniqueValue() {
            OrderService service = new OrderService(uow);
            int n = 100;
            Order row = Factories.newOrder(1);
            var first = service.createOrder(createOf(row));
            Order again = Factories.newOrder(2);
            again.setCode(first.code());
            assertThrows(ConflictException.class, () -> service.createOrder(createOf(again)));
        }

        @Test
        void keepsItsOwnUniqueValue() {
            OrderService service = new OrderService(uow);
            int n = 100;
            Order row = Factories.newOrder(1);
            var created = service.createOrder(createOf(row));
            service.updateOrder(created.id(), new OrderUpdate(Patch.of(created.code()), Patch.absent(), Patch.absent()));
        }

        @Test
        void saysWhenARowIsMissing() {
            OrderService service = new OrderService(uow);
            assertThrows(NotFoundException.class, () -> service.getOrder("ffffffffffffffffffffffff"));
        }

        @Test
        void addsAndRemovesOneItemOfLines() {
            OrderService service = new OrderService(uow);
            int n = 100;
            Order row = Factories.newOrder(1);
            var created = service.createOrder(createOf(row));
            int before = created.lines() == null ? 0 : created.lines().size();
            Order.Line item = Factories.newOrderLine(7);
            var added = service.addLine(created.id(), item);
            assertEquals(before + 1, added.lines().size());
            var removed = service.removeLine(created.id(), added.lines().get(before).getId());
            assertEquals(before, removed.lines().size());
            assertThrows(NotFoundException.class, () -> service.removeLine(created.id(), "ffffffffffffffffffffffff"));
        }

        @Test
        void deletesARow() {
            OrderService service = new OrderService(uow);
            int n = 100;
            Order row = Factories.newOrder(1);
            var created = service.createOrder(createOf(row));
            service.deleteOrder(created.id());
            assertThrows(NotFoundException.class, () -> service.getOrder(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static OrderCreate createOf(Order row) {
        return new OrderCreate(row.getCode(), row.getLines(), row.getShipping());
    }
}

