        void refusesAMissingValue() {
            ShipmentService service = new ShipmentService(uow);
            int n = 100;
            Shipment row = Factories.newShipment(1);
            row.setParcel(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createShipment(createOf(row)));
            assertEquals(List.of("parcel"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void saysWhenARowIsMissing() {
            ShipmentService service = new ShipmentService(uow);
            assertThrows(NotFoundException.class, () -> service.getShipment("ffffffffffffffffffffffff"));
        }

        @Test
        void addsAndRemovesOneItemOfStops() {
            ShipmentService service = new ShipmentService(uow);
            int n = 100;
            Shipment row = Factories.newShipment(1);
            var created = service.createShipment(createOf(row));
            int before = created.stops() == null ? 0 : created.stops().size();
            Shipment.Stop item = Factories.newShipmentStop(7);
            var added = service.addStop(created.id(), item);
            assertEquals(before + 1, added.stops().size());
            var removed = service.removeStop(created.id(), before);
            assertEquals(before, removed.stops().size());
            assertThrows(NotFoundException.class, () -> service.removeStop(created.id(), 99));
        }

        @Test
        void deletesARow() {
            ShipmentService service = new ShipmentService(uow);
            int n = 100;
            Shipment row = Factories.newShipment(1);
            var created = service.createShipment(createOf(row));
            service.deleteShipment(created.id());
            assertThrows(NotFoundException.class, () -> service.getShipment(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static ShipmentCreate createOf(Shipment row) {
        return new ShipmentCreate(row.getParcel(), row.getStops());
    }
}

